671:       resolveDistanceAutoRouteEta({
672:         targetKm: km,
673:         mileageTotalMeters: getUserMileage?.().totalMeters ?? null,
674:         mileageTotalSec: getUserMileage?.().totalSec ?? null,
675:       }),
676:     );
677:     distanceNumber.value = km.toFixed(1);
678:     if (distanceDirectionChecked) {
679:       minusBtn.disabled = km <= DISTANCE_AUTO_ROUTE_KM_MIN;
680:       plusBtn.disabled = km >= DISTANCE_AUTO_ROUTE_KM_MAX;
681:       // 원과 함께 안내 `{N}` 즉시 갱신(검색/결과 문구는 덮지 않음)
682:       if (autoRouteStatus.dataset.phase === "direction") {
