705:   function applyDistanceDirectionMode(checked: boolean) {
706:     distanceDirectionChecked = checked;
707:     /*
708:      * 브리지는 **그때그때 다시 찾는다**(2026-09-18 Chief).
709:      * `mapBridge` 는 팝업을 만들 때 한 번 잡아 둔 값이라, 그 시점에 아직 등록 전이었거나
710:      * 이후 다시 등록됐으면 `null`·낡은 객체를 붙들고 있다 — 그러면 이 호출이 조용히
711:      * 사라져 체크를 풀어도 훅은 아무것도 모른다(반경 원이 그대로 남던 원인).
712:      *
713:      * 지시30 — 경로는 하나로 유지. 체크에 따라 패널 접기만 함께 바꾸고(UI),
714:      * 수동 경로 준비/토큰 disabled 가 낡지 않게 syncProfileUi 도 갱신한다.
715:      * 핀·거리 값·탐색 콜백은 여기서 건드리지 않는다(아래 정리 호출 제외).
716:      */
717:     getDistanceAutoRouteMapBridge()?.setDistanceDirectionMode?.(checked);
718:     if (checked) {
719:       routeDistanceExpanded = true;
720:       routeLocationExpanded = false;
721:     } else {
722:       routeLocationExpanded = true;
723:       routeDistanceExpanded = false;
724:     }
725:     syncDistanceModeUi();
726:     syncRouteLocationPanel();
727:     syncRouteDistancePanel();
728:     syncProfileUi();
729:     if (!checked) {
730:       onClearAutoRouteClickDebugMarker?.();
731:       // 원을 소유한 쪽에 직접 지우라고 말한다 — 훅의 정리에만 기대지 않는다.
732:       onClearDistanceAutoRouteCircle?.();
733:       setInlinePhase("idle");
734:       return;
735:     }
736:     previewCircleForTargetKm(targetKm);
737:     tryArmDirectionPickIfChecked();
738:   }
