745:   function stepTargetKm(deltaKm: number) {
746:     if (!distanceDirectionChecked) return;
747:     const next = Math.min(
748:       DISTANCE_AUTO_ROUTE_KM_MAX,
749:       Math.max(
750:         DISTANCE_AUTO_ROUTE_KM_MIN,
751:         Math.round((targetKm + deltaKm) / DISTANCE_AUTO_ROUTE_KM_STEP) * DISTANCE_AUTO_ROUTE_KM_STEP,
752:       ),
753:     );
754:     syncDistanceInputs(next);
755:     previewCircleForTargetKm(next);
756:     tryArmDirectionPickIfChecked();
757:   }
758: 
759:   function setInlinePhase(
760:     phase: "idle" | "direction" | "searching" | "found" | "failed",
761:     message?: string,
762:   ) {
763:     autoRouteStatus.className = "map-view__pick-auto-route-status";
764:     autoRouteStatus.dataset.phase = phase;
765:     if (phase === "idle") {
766:       autoRouteStatus.textContent = "";
767:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--idle");
768:       syncRouteStatusSlot();
769:       return;
770:     }
771:     if (phase === "direction") {
772:       autoRouteStatus.textContent =
773:         message ?? formatDistanceAutoRouteDirectionClickHint(targetKm);
774:       syncRouteStatusSlot();
775:       return;
776:     }
777:     if (phase === "searching") {
778:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--searching");
779:       autoRouteStatus.textContent =
780:         message ?? "목표 거리에 맞는 도로 경로를 찾는 중입니다…";
781:       syncRouteStatusSlot();
782:       return;
783:     }
784:     if (phase === "failed") {
785:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--failed");
786:       autoRouteStatus.textContent = message ?? "경로를 찾지 못했습니다.";
787:       syncRouteStatusSlot();
788:       return;
789:     }
790:     autoRouteStatus.classList.add("map-view__pick-auto-route-status--found");
791:     autoRouteStatus.textContent = message ?? "경로를 찾았습니다.";
792:     syncRouteStatusSlot();
793:   }
