795:   function tryArmDirectionPick() {
796:     if (!distanceDirectionChecked) return;
797:     const start = getRouteStart();
798:     if (!start || typeof onArmDirectionPick !== "function") return;
799:     if (getRouteTokenInsufficient?.()) {
800:       setInlinePhase("failed", ROUTE_TOKEN_INSUFFICIENT_HINT);
801:       return;
802:     }
803:     const parsed = Number.parseFloat(distanceNumber.value);
804:     const validated = validateDistanceAutoRouteTargetKm(parsed);
805:     if (!validated.ok) {
806:       setInlinePhase("failed", validated.message);
807:       return;
808:     }
809:     syncDistanceInputs(validated.km);
810:     previewCircleForTargetKm(validated.km);
811:     const result = onArmDirectionPick({
812:       start,
813:       profile: currentProfile,
814:       targetKm: validated.km,
815:     });
816:     if (!result.ok) {
817:       setInlinePhase("failed", result.message);
818:       return;
819:     }
820:     autoSessionActive = true;
821:     const rerouteReady = autoRouteStatus.dataset.phase === "found";
822:     setInlinePhase(
823:       "direction",
824:       rerouteReady || autoRouteStatusMessage === DISTANCE_AUTO_ROUTE_REROUTE_HINT
825:         ? DISTANCE_AUTO_ROUTE_REROUTE_HINT
826:         : formatDistanceAutoRouteDirectionClickHint(validated.km),
827:     );
828:     onDirectionPickArmed?.();
829:   }
