1363: /* MapZoomGlobeControl — 지구 전체 보기(줌 +/- 아래) */
1364: .map-view .mapboxgl-ctrl-globe-view .mapboxgl-ctrl-icon {
1365:   background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 22 22' fill='none' stroke='%23333' stroke-width='1.55' stroke-linecap='round' stroke-linejoin='round'%3E%3Ccircle cx='11' cy='11' r='8.25'/%3E%3Cellipse cx='11' cy='11' rx='3.25' ry='8.25'/%3E%3Cpath d='M2.75 11h16.5M11 2.75v16.5'/%3E%3C/svg%3E");
1366:   background-size: 18px 18px;
1367: }
