1383:   --br-card-above-clock: 10px; /* e2e 는 ≥8px 를 엄격(<)하게 본다 — 경계값 8 에 걸리지 않게 여유 */
1384:   --br-altitude-box-width: 74px; /* 「고도 999.9 km」 최대 폭 */
1385:   --br-altitude-box-height: 16px;
1386:   --br-scale-box-width: 120px; /* ScaleControl maxWidth(막대 최대 길이) */
1387:   --br-scale-box-height: 16px;
1388: }
