input.newString:
/*
 * 지시34 — 거리 화면. autoRouteSection이 거리뷰 컨테이너(계약 append 유지)라
 * 별도 section을 두지 않는다. 긴 2문단 가이드 대신 기존 방향 status 안내를 쓴다.
 * Start/수단행/위치버튼/두 토글/checkbox는 거리 화면에 표시하지 않는다.
 */
const routeDistanceHead = document.createElement("div");
routeDistanceHead.className = "map-view__pick-route-distance-head";
const routeDistanceBackBtn = document.createElement("button");
routeDistanceBackBtn.type = "button";
routeDistanceBackBtn.className = "map-view__pick-btn map-view__pick-btn--route-back";
routeDistanceBackBtn.textContent = "‹ 위치 선택";
routeDistanceBackBtn.setAttribute("aria-label", "위치 선택으로 돌아가기");
routeDistanceBackBtn.onclick = () => {
  if (routePickView === "location") return;
  applyDistanceDirectionMode(false);
};
const routeDistanceTitle = document.createElement("p");
routeDistanceTitle.className = "map-view__pick-route-distance-title";
routeDistanceTitle.textContent = "목표 거리로 경로 만들기";
routeDistanceHead.append(routeDistanceBackBtn, routeDistanceTitle);

/*
 * 작은 출발 요약. 실제 currentProfile과 동기화하고, 클릭 지점 주소를
 * 출발 주소로 오표시하지 않는다(출발 설정 여부·수단만).
 */
const routeDistanceSummary = document.createElement("p");
routeDistanceSummary.className = "map-view__pick-route-distance-summary";
routeDistanceSummary.setAttribute("aria-live", "polite");
autoRouteSection.append(routeDistanceHead, routeDistanceSummary);
autoRouteSection.append(distanceRow, autoRouteStatusSlot);

/*
 * 지시34 — 단일 화면 동기화. 관련 hidden/classes/버튼/요약을 한 곳에서 갱신한다.
 * 화면 전환은 값을 초기화하지 않는다(핀·목표거리·수단·토큰·검색/오류 상태 유지).
 * 함수 선언이라 호이스팅되고, 첫 호출은 아래 초기 동기화(모든 DOM 정의 뒤)다.
 */
function syncRoutePickView() {
  const inDistance = routePickView === "distance";
  routeLocationView.hidden = inDistance;
  autoRouteSection.hidden = !inDistance;
  addressEl.hidden = inDistance;
  metaEl.hidden = inDistance;
  const available = pins.start && typeof onArmDirectionPick === "function";
  routeDistanceEnterBtn.disabled = !available;
  routeDistanceSummary.textContent = `출발 설정됨 · ${ROUTE_PROFILE_KO[currentProfile]}`;
}

function syncAutoRouteUi() {
  const available = pins.start && typeof onArmDirectionPick === "function";
  /* 출발 전제 없으면 거리뷰에 머물지 않는다 — location뷰로 돌리고 상태만 idle 정리. */
  if (!available) {
    routePickView = "location";
    setInlinePhase("idle");
    onClearDistanceAutoRouteCircle?.();
  }
  /* 사용자 값(핀·목표거리·수단)은 리셋하지 않는다 — 전제 정리와 뷰 동기화만 다룬다. */
  syncRoutePickView();
}
syncAutoRouteUi();

input.oldString:
/* 지시30 — 거리 선택 접이식 패널. 내용은 기존 checkbox/±/입력/프리셋/ETA. 상태 슬롯은 분리해 접어도 볼 수 있게 한다. */
const routeDistanceSection = document.createElement("div");
routeDistanceSection.className =
  "map-view__pick-route-panel map-view__pick-route-panel--distance";
const routeDistanceToggle = document.createElement("button");
routeDistanceToggle.type = "button";
routeDistanceToggle.className = "map-view__pick-route-toggle";
routeDistanceToggle.setAttribute("aria-controls", "map-view-pick-route-distance-content");
const routeDistanceTitle = document.createElement("span");
routeDistanceTitle.className = "map-view__pick-route-toggle-label";
routeDistanceTitle.textContent = "거리 선택";
const routeDistanceCaret = document.createElement("span");
routeDistanceCaret.className = "map-view__pick-route-toggle-caret";
routeDistanceCaret.setAttribute("aria-hidden", "true");
routeDistanceCaret.textContent = "▾";
routeDistanceToggle.append(routeDistanceTitle, routeDistanceCaret);
const routeDistanceContent = document.createElement("div");
routeDistanceContent.className =
  "map-view__pick-route-panel-content map-view__pick-route-panel-content--distance";
routeDistanceContent.id = "map-view-pick-route-distance-content";
routeDistanceContent.append(distanceRow);
/* 지시31 — 토글은 공통 한 행 toolbar로 이동. 패널은 content만 갖는다. */
routeDistanceSection.append(routeDistanceContent);
autoRouteSection.append(routeDistanceSection, autoRouteStatusSlot);

/* 지시31 — 현재 위치/거리 토글 공통 한 행 toolbar. 44px 두 버튼 나란히, 두 줄 쌓기 없음. */
const routeModeToolbar = document.createElement("div");
routeModeToolbar.className = "map-view__pick-route-toolbar";
routeModeToolbar.setAttribute("role", "group");
routeModeToolbar.setAttribute("aria-label", "경로 탐색 모드");
routeModeToolbar.append(routeLocationToggle, routeDistanceToggle);

function syncRouteLocationPanel() {
  routeLocationToggle.setAttribute("aria-expanded", String(routeLocationExpanded));
  routeLocationContent.hidden = !routeLocationExpanded;
  routeLocationCaret.textContent = routeLocationExpanded ? "▾" : "▸";
}

function syncRouteDistancePanel() {
  routeDistanceToggle.setAttribute("aria-expanded", String(routeDistanceExpanded));
  routeDistanceContent.hidden = !routeDistanceExpanded;
  routeDistanceCaret.textContent = routeDistanceExpanded ? "▾" : "▸";
  syncRouteStatusSlot();
}

function syncRouteStatusSlot() {
  /* 펼침 시 기존 reserve 유지(항상 자리). 접힘 시 실제 메시지가 있을 때만 표시해 높이를 아낀다. */
  const phase = autoRouteStatus.dataset.phase ?? "idle";
  autoRouteStatusSlot.hidden = !routeDistanceExpanded && phase === "idle";
}

function syncAutoRouteUi() {
  const available = pins.start && typeof onArmDirectionPick === "function";
  autoRouteSection.hidden = !available;
  /* 지시31 — distance toggle은 출발 prerequisite 없을 때 hidden. 위치 toggle은 접근 가능 유지. */
  routeDistanceToggle.hidden = !available;
  if (!available) {
    setInlinePhase("idle");
    onClearDistanceAutoRouteCircle?.();
  }
  /* 사용자 펼침 상태는 리셋하지 않는다 — prerequisite hidden 과 상태 슬롯만 다룬다. */
  syncRouteStatusSlot();
}

/* 펼치기/접기는 UI만 — 핀·거리·수단·토큰·탐색 콜백을 건드리지 않는다. 둘 다 펼칠 수 있다. */
routeLocationToggle.addEventListener("click", () => {
  routeLocationExpanded = !routeLocationExpanded;
  syncRouteLocationPanel();
});
routeDistanceToggle.addEventListener("click", () => {
  routeDistanceExpanded = !routeDistanceExpanded;
  syncRouteDistancePanel();
});
syncRouteLocationPanel();
syncRouteDistancePanel();
syncAutoRouteUi();

