/* 지시34 — 위치/거리 별도 화면. 같은 wrap, 내용만 교체. 토글/toolbar는 제거. */
.map-view__pick-route-view {
  min-width: 0;
  max-width: 100%;
}

.map-view__pick-route-view--location {
  margin-top: 0.06rem;
}

.map-view__pick-route-view--location .map-view__pick-actions--pin-row {
  margin-top: 0.08rem;
}

/* 지시34 — '거리 ›' 진입. profile row 끝에 붙고 별도 중간행 없음. 44px는 이 버튼만. */
.map-view__pick-btn--route-enter {
  flex: 1 1 0;
  min-width: 44px;
  min-height: 44px;
  align-self: center;
  padding: 0.26rem 0.5rem;
  background: #EFF6FF;
  border-color: #2563EB;
  color: #1D4ED8;
  white-space: nowrap;
}

.map-view__pick-btn--route-enter:hover:not(:disabled) {
  background: #DBEAFE;
  border-color: #1D4ED8;
}

/* 지시34 — 거리 화면 상단. '‹ 위치 선택' 복귀 + 제목 한 행(별도 중간행 없음). */
.map-view__pick-route-distance-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  max-width: 100%;
  margin-top: 0.06rem;
}

.map-view__pick-btn--route-back {
  flex: 0 0 auto;
  min-width: 44px;
  min-height: 44px;
  padding: 0.26rem 0.5rem;
  background: #F1F5F9;
  border-color: #CBD5E1;
  color: #1F2937;
  white-space: nowrap;
}

.map-view__pick-btn--route-back:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #CBD5E1;
}

.map-view__pick-route-distance-title {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.3;
  color: #1F2937;
}

/* 지시34 — 작은 출발 요약. 실제 수단과 동기화, 클릭 지점 주소 오표시 없음. */
.map-view__pick-route-distance-summary {
  margin: 0.1rem 0 0;
  font-size: 0.68rem;
  line-height: 1.35;
  color: rgba(71, 85, 105, 0.9);
}

