/* 지시30 — 위치/거리 선택 접이식 패널. 토글 높이를 최소로, 기존 font/컨트롤 크기 유지. */
.map-view__pick-route-panel {
  min-width: 0;
  max-width: 100%;
}

/* 지시31 — 위치/거리 토글 공통 한 행 toolbar. 두 button 44px 나란히, 두 줄 쌓기 없음. */
.map-view__pick-route-toolbar {
  display: flex;
