  gap: 0.4rem;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 0.14rem 0.2rem;
  border: 0;
  border-radius: 0.35rem;
  background: transparent;
